    36→type customProcessingFn func(context.Context, state.BeaconState) error
    37→
    38→// ExecuteStateTransition defines the procedure for a state transition function.
    39→//
    40→// Note: This method differs from the spec pseudocode as it uses a batch signature verification.
    41→// See: ExecuteStateTransitionNoVerifyAnySig
    42→//
    43→// Spec pseudocode definition:
    44→//
    45→//	def state_transition(state: BeaconState, signed_block: ReadOnlySignedBeaconBlock, validate_result: bool=True) -> None:
    46→//	  block = signed_block.message
    47→//	  # Process slots (including those with no blocks) since block
    48→//	  process_slots(state, block.slot)
    49→//	  # Verify signature
    50→//	  if validate_result:
    51→//	      assert verify_block_signature(state, signed_block)
    52→//	  # Process block
    53→//	  process_block(state, block)
    54→//	  # Verify state root
    55→//	  if validate_result:
    56→//	      assert block.state_root == hash_tree_root(state)
    57→func ExecuteStateTransition(
    58→	ctx context.Context,
    59→	state state.BeaconState,
    60→	signed interfaces.ReadOnlySignedBeaconBlock,
    61→) (state.BeaconState, error) {
    62→	if ctx.Err() != nil {
    63→		return nil, ctx.Err()
    64→	}
    65→	if err := blocks.BeaconBlockIsNil(signed); err != nil {
    66→		return nil, err
    67→	}
    68→
    69→	ctx, span := prysmTrace.StartSpan(ctx, "core.state.ExecuteStateTransition")
    70→	defer span.End()
    71→	var err error
    72→
    73→	set, postState, err := ExecuteStateTransitionNoVerifyAnySig(ctx, state, signed)
    74→	if err != nil {
    75→		return nil, errors.Wrap(err, "could not execute state transition")
    76→	}
    77→
    78→	var valid bool
    79→	if features.Get().EnableVerboseSigVerification {
    80→		valid, err = set.VerifyVerbosely()
    81→	} else {
    82→		valid, err = set.Verify()
    83→	}
    84→	if err != nil {
    85→		return nil, errors.Wrap(err, "could not batch verify signature")
    86→	}
    87→	if !valid {
    88→		return nil, errors.New("signature in block failed to verify")
    89→	}
    90→
    91→	return postState, nil
    92→}
    93→
    94→// ProcessSlot happens every slot and focuses on the slot counter and block roots record updates.
    95→// It happens regardless if there's an incoming block or not.
    96→// Spec pseudocode definition:
    97→//
    98→//	def process_slot(state: BeaconState) -> None:
    99→//	  # Cache state root
   100→//	  previous_state_root = hash_tree_root(state)
   101→//	  state.state_roots[state.slot % SLOTS_PER_HISTORICAL_ROOT] = previous_state_root
   102→//	  # Cache latest block header state root
   103→//	  if state.latest_block_header.state_root == Bytes32():
   104→//	      state.latest_block_header.state_root = previous_state_root
   105→//	  # Cache block root
   106→//	  previous_block_root = hash_tree_root(state.latest_block_header)
   107→//	  state.block_roots[state.slot % SLOTS_PER_HISTORICAL_ROOT] = previous_block_root
   108→func ProcessSlot(ctx context.Context, state state.BeaconState) (state.BeaconState, error) {
   109→	ctx, span := prysmTrace.StartSpan(ctx, "core.state.ProcessSlot")
   110→	defer span.End()
   111→	span.SetAttributes(prysmTrace.Int64Attribute("slot", int64(state.Slot()))) // lint:ignore uintcast -- This is OK for tracing.
   112→
   113→	prevStateRoot, err := state.HashTreeRoot(ctx)
   114→	if err != nil {
   115→		return nil, err
   116→	}
   117→	if err := state.UpdateStateRootAtIndex(
   118→		uint64(state.Slot()%params.BeaconConfig().SlotsPerHistoricalRoot),
   119→		prevStateRoot,
   120→	); err != nil {
   121→		return nil, err
   122→	}
   123→
   124→	zeroHash := params.BeaconConfig().ZeroHash
   125→	// Cache latest block header state root.
   126→	header := state.LatestBlockHeader()
   127→	if header.StateRoot == nil || bytes.Equal(header.StateRoot, zeroHash[:]) {
   128→		header.StateRoot = prevStateRoot[:]
   129→		if err := state.SetLatestBlockHeader(header); err != nil {
   130→			return nil, err
   131→		}
   132→	}
   133→	prevBlockRoot, err := state.LatestBlockHeader().HashTreeRoot()
   134→	if err != nil {
   135→		tracing.AnnotateError(span, err)
   136→		return nil, errors.Wrap(err, "could not determine prev block root")
   137→	}
   138→	// Cache the block root.
   139→	if err := state.UpdateBlockRootAtIndex(
   140→		uint64(state.Slot()%params.BeaconConfig().SlotsPerHistoricalRoot),
   141→		prevBlockRoot,
   142→	); err != nil {
   143→		return nil, err
   144→	}
   145→	return state, nil
   146→}
   147→
   148→// ProcessSlotsUsingNextSlotCache processes slots by using next slot cache for higher efficiency.
   149→func ProcessSlotsUsingNextSlotCache(
   150→	ctx context.Context,
   151→	parentState state.BeaconState,
   152→	parentRoot []byte,
   153→	slot primitives.Slot) (state.BeaconState, error) {
   154→	ctx, span := prysmTrace.StartSpan(ctx, "core.state.ProcessSlotsUsingNextSlotCache")
   155→	defer span.End()
   156→
   157→	nextSlotState := NextSlotState(parentRoot, slot)
   158→	if nextSlotState != nil {
   159→		parentState = nextSlotState
   160→	}
   161→	if parentState.Slot() == slot {
   162→		return parentState, nil
   163→	}
   164→
   165→	var err error
   166→	parentState, err = ProcessSlots(ctx, parentState, slot)
   167→	if err != nil {
   168→		return nil, errors.Wrap(err, "could not process slots")
   169→	}
   170→	return parentState, nil
   171→}
   172→
   173→// ProcessSlotsIfPossible executes ProcessSlots on the input state when target slot is above the state's slot.
   174→// Otherwise, it returns the input state unchanged.
   175→func ProcessSlotsIfPossible(ctx context.Context, state state.BeaconState, targetSlot primitives.Slot) (state.BeaconState, error) {
   176→	if targetSlot > state.Slot() {
   177→		return ProcessSlots(ctx, state, targetSlot)
   178→	}
   179→	return state, nil
   180→}
   181→
   182→// ProcessSlots includes core slot processing as well as a cache
   183→func ProcessSlots(ctx context.Context, state state.BeaconState, slot primitives.Slot) (state.BeaconState, error) {
   184→	ctx, span := prysmTrace.StartSpan(ctx, "core.state.ProcessSlots")
   185→	defer span.End()
   186→	if state == nil || state.IsNil() {
   187→		return nil, errors.New("nil state")
   188→	}
   189→	span.SetAttributes(prysmTrace.Int64Attribute("slots", int64(slot)-int64(state.Slot()))) // lint:ignore uintcast -- This is OK for tracing.
   190→
   191→	// The block must have a higher slot than parent state.
   192→	if state.Slot() >= slot {
   193→		err := fmt.Errorf("expected state.slot %d < slot %d", state.Slot(), slot)
   194→		tracing.AnnotateError(span, err)
   195→		return nil, err
   196→	}
   197→
   198→	highestSlot := state.Slot()
   199→	key, err := cacheKey(ctx, state)
   200→	if err != nil {
   201→		return nil, err
   202→	}
   203→
   204→	// Restart from cached value, if one exists.
   205→	cachedState, err := SkipSlotCache.Get(ctx, key)
   206→	if err != nil {
   207→		return nil, err
   208→	}
   209→
   210→	if cachedState != nil && !cachedState.IsNil() && cachedState.Slot() < slot {
   211→		highestSlot = cachedState.Slot()
   212→		state = cachedState
   213→	}
   214→	if err := SkipSlotCache.MarkInProgress(key); errors.Is(err, cache.ErrAlreadyInProgress) {
   215→		cachedState, err = SkipSlotCache.Get(ctx, key)
   216→		if err != nil {
   217→			return nil, err
   218→		}
   219→		if cachedState != nil && !cachedState.IsNil() && cachedState.Slot() < slot {
   220→			highestSlot = cachedState.Slot()
   221→			state = cachedState
   222→		}
   223→	} else if err != nil {
   224→		return nil, err
   225→	}
   226→	defer func() {
   227→		SkipSlotCache.MarkNotInProgress(key)
   228→	}()
   229→	state, err = ProcessSlotsCore(ctx, span, state, slot, cacheBestBeaconStateOnErrFn(highestSlot, key))
   230→	if err != nil {
   231→		return nil, err
   232→	}
   233→	if highestSlot < state.Slot() {
   234→		SkipSlotCache.Put(ctx, key, state)
   235→	}
   236→
   237→	return state, nil
   238→}
   239→
   240→func cacheBestBeaconStateOnErrFn(highestSlot primitives.Slot, key [32]byte) customProcessingFn {
   241→	return func(ctx context.Context, state state.BeaconState) error {
   242→		if ctx.Err() != nil {
   243→			// Cache last best value.
   244→			if highestSlot < state.Slot() {
   245→				SkipSlotCache.Put(ctx, key, state)
   246→			}
   247→			return ctx.Err()
   248→		}
   249→		return nil
   250→	}
   251→}
   252→
   253→// ProcessSlotsCore process through skip slots and apply epoch transition when it's needed
   254→//
   255→// Spec pseudocode definition:
   256→//
   257→//	def process_slots(state: BeaconState, slot: Slot) -> None:
   258→//	  assert state.slot < slot
   259→//	  while state.slot < slot:
   260→//	      process_slot(state)
   261→//	      # Process epoch on the start slot of the next epoch
   262→//	      if (state.slot + 1) % SLOTS_PER_EPOCH == 0:
   263→//	          process_epoch(state)
   264→//	      state.slot = Slot(state.slot + 1)
   265→func ProcessSlotsCore(ctx context.Context, span trace.Span, state state.BeaconState, slot primitives.Slot, fn customProcessingFn) (state.BeaconState, error) {
   266→	var err error
   267→	for state.Slot() < slot {
   268→		if fn != nil {
   269→			if err = fn(ctx, state); err != nil {
   270→				tracing.AnnotateError(span, err)
   271→				return nil, err
   272→			}
   273→		}
   274→		state, err = ProcessSlot(ctx, state)
   275→		if err != nil {
   276→			tracing.AnnotateError(span, err)
   277→			return nil, errors.Wrap(err, "could not process slot")
   278→		}
   279→
   280→		state, err = ProcessEpoch(ctx, state)
   281→		if err != nil {
   282→			tracing.AnnotateError(span, err)
   283→			return nil, err
   284→		}
   285→
   286→		if err := state.SetSlot(state.Slot() + 1); err != nil {
   287→			tracing.AnnotateError(span, err)
   288→			return nil, errors.Wrap(err, "failed to increment state slot")
   289→		}
   290→
   291→		state, err = UpgradeState(ctx, state)
   292→		if err != nil {
   293→			tracing.AnnotateError(span, err)
   294→			return nil, errors.Wrap(err, "failed to upgrade state")
   295→		}
   296→
   297→		logBlobLimitIncrease(state.Slot())
   298→	}
   299→	return state, nil
   300→}
   301→
   302→// ProcessEpoch is a wrapper on fork specific epoch processing
   303→func ProcessEpoch(ctx context.Context, state state.BeaconState) (state.BeaconState, error) {
   304→	var err error
   305→	if time.CanProcessEpoch(state) {
   306→		if state.Version() >= version.Fulu {
   307→			if err = fulu.ProcessEpoch(ctx, state); err != nil {
   308→				return nil, errors.Wrap(err, fmt.Sprintf("could not process %s epoch", version.String(state.Version())))
   309→			}
   310→		} else if state.Version() >= version.Electra {
   311→			if err = electra.ProcessEpoch(ctx, state); err != nil {
   312→				return nil, errors.Wrap(err, fmt.Sprintf("could not process %s epoch", version.String(state.Version())))
   313→			}
   314→		} else if state.Version() >= version.Altair {
   315→			if err = altair.ProcessEpoch(ctx, state); err != nil {
   316→				return nil, errors.Wrap(err, fmt.Sprintf("could not process %s epoch", version.String(state.Version())))
   317→			}
   318→		} else {
   319→			state, err = ProcessEpochPrecompute(ctx, state)
   320→			if err != nil {
   321→				return nil, errors.Wrap(err, "could not process epoch with optimizations")
   322→			}
   323→		}
   324→	}
   325→	return state, err
   326→}
