   328→// UpgradeState upgrades the state to the next version if possible.
   329→func UpgradeState(ctx context.Context, state state.BeaconState) (state.BeaconState, error) {
   330→	ctx, span := prysmTrace.StartSpan(ctx, "core.state.UpgradeState")
   331→	defer span.End()
   332→
   333→	var err error
   334→
   335→	slot := state.Slot()
   336→	upgraded := false
   337→
   338→	if time.CanUpgradeToAltair(slot) {
   339→		state, err = altair.UpgradeToAltair(ctx, state)
   340→		if err != nil {
   341→			tracing.AnnotateError(span, err)
   342→			return nil, err
   343→		}
   344→		upgraded = true
   345→	}
   346→
   347→	if time.CanUpgradeToBellatrix(slot) {
   348→		state, err = execution.UpgradeToBellatrix(state)
   349→		if err != nil {
   350→			tracing.AnnotateError(span, err)
   351→			return nil, err
   352→		}
   353→		upgraded = true
   354→	}
   355→
   356→	if time.CanUpgradeToCapella(slot) {
   357→		state, err = capella.UpgradeToCapella(state)
   358→		if err != nil {
   359→			tracing.AnnotateError(span, err)
   360→			return nil, err
   361→		}
   362→		upgraded = true
   363→	}
   364→
   365→	if time.CanUpgradeToDeneb(slot) {
   366→		state, err = deneb.UpgradeToDeneb(state)
   367→		if err != nil {
   368→			tracing.AnnotateError(span, err)
   369→			return nil, err
   370→		}
   371→		upgraded = true
   372→	}
   373→
   374→	if time.CanUpgradeToElectra(slot) {
   375→		state, err = electra.UpgradeToElectra(state)
   376→		if err != nil {
   377→			tracing.AnnotateError(span, err)
   378→			return nil, err
   379→		}
   380→		upgraded = true
   381→	}
   382→
   383→	if time.CanUpgradeToFulu(slot) {
   384→		state, err = fulu.UpgradeToFulu(ctx, state)
   385→		if err != nil {
   386→			tracing.AnnotateError(span, err)
   387→			return nil, err
   388→		}
   389→		upgraded = true
   390→	}
   391→
   392→	if upgraded {
   393→		log.WithField("version", version.String(state.Version())).Info("Upgraded state to")
   394→	}
   395→
   396→	return state, nil
   397→}
