   399→// VerifyOperationLengths verifies that block operation lengths are valid.
   400→func VerifyOperationLengths(_ context.Context, state state.BeaconState, b interfaces.ReadOnlyBeaconBlock) (state.BeaconState, error) {
   401→	if b == nil || b.IsNil() {
   402→		return nil, blocks.ErrNilBeaconBlock
   403→	}
   404→	body := b.Body()
   405→
   406→	if uint64(len(body.ProposerSlashings())) > params.BeaconConfig().MaxProposerSlashings {
   407→		return nil, fmt.Errorf(
   408→			"number of proposer slashings (%d) in block body exceeds allowed threshold of %d",
   409→			len(body.ProposerSlashings()),
   410→			params.BeaconConfig().MaxProposerSlashings,
   411→		)
   412→	}
   413→
   414→	maxSlashings := params.BeaconConfig().MaxAttesterSlashings
   415→	if body.Version() >= version.Electra {
   416→		maxSlashings = params.BeaconConfig().MaxAttesterSlashingsElectra
   417→	}
   418→	if uint64(len(body.AttesterSlashings())) > maxSlashings {
   419→		return nil, fmt.Errorf(
   420→			"number of attester slashings (%d) in block body exceeds allowed threshold of %d",
   421→			len(body.AttesterSlashings()),
   422→			maxSlashings,
   423→		)
   424→	}
   425→
   426→	maxAttestations := params.BeaconConfig().MaxAttestations
   427→	if body.Version() >= version.Electra {
   428→		maxAttestations = params.BeaconConfig().MaxAttestationsElectra
   429→	}
   430→	if uint64(len(body.Attestations())) > maxAttestations {
   431→		return nil, fmt.Errorf(
   432→			"number of attestations (%d) in block body exceeds allowed threshold of %d",
   433→			len(body.Attestations()),
   434→			maxAttestations,
   435→		)
   436→	}
   437→
   438→	if uint64(len(body.VoluntaryExits())) > params.BeaconConfig().MaxVoluntaryExits {
   439→		return nil, fmt.Errorf(
   440→			"number of voluntary exits (%d) in block body exceeds allowed threshold of %d",
   441→			len(body.VoluntaryExits()),
   442→			params.BeaconConfig().MaxVoluntaryExits,
   443→		)
   444→	}
   445→	eth1Data := state.Eth1Data()
   446→	if eth1Data == nil {
   447→		return nil, errors.New("nil eth1data in state")
   448→	}
   449→
   450→	if state.Version() < version.Electra {
   451→		// Deneb specs
   452→		//  # Verify that outstanding deposits are processed up to the maximum number of deposits
   453→		//    assert len(body.deposits) == min(MAX_DEPOSITS, state.eth1_data.deposit_count - state.eth1_deposit_index)
   454→		if state.Eth1DepositIndex() > eth1Data.DepositCount {
   455→			return nil, fmt.Errorf("expected state.deposit_index %d <= eth1data.deposit_count %d", state.Eth1DepositIndex(), eth1Data.DepositCount)
   456→		}
   457→		maxDeposits := min(params.BeaconConfig().MaxDeposits, eth1Data.DepositCount-state.Eth1DepositIndex())
   458→		// Verify outstanding deposits are processed up to max number of deposits
   459→		if uint64(len(body.Deposits())) != maxDeposits {
   460→			return nil, fmt.Errorf("incorrect outstanding deposits in block body, wanted: %d, got: %d",
   461→				maxDeposits, len(body.Deposits()))
   462→		}
   463→	} else {
   464→		// Electra
   465→		if err := electra.VerifyBlockDepositLength(body, state); err != nil {
   466→			return nil, errors.Wrap(err, "failed to verify block deposit length")
   467→		}
   468→	}
   469→
   470→	return state, nil
   471→}
   472→
   473→// ProcessEpochPrecompute describes the per epoch operations that are performed on the beacon state.
   474→// It's optimized by pre computing validator attested info and epoch total/attested balances upfront.
   475→func ProcessEpochPrecompute(ctx context.Context, state state.BeaconState) (state.BeaconState, error) {
   476→	ctx, span := prysmTrace.StartSpan(ctx, "core.state.ProcessEpochPrecompute")
   477→	defer span.End()
   478→	span.SetAttributes(prysmTrace.Int64Attribute("epoch", int64(time.CurrentEpoch(state)))) // lint:ignore uintcast -- This is OK for tracing.
   479→
   480→	if state == nil || state.IsNil() {
   481→		return nil, errors.New("nil state")
   482→	}
   483→	vp, bp, err := precompute.New(ctx, state)
   484→	if err != nil {
   485→		return nil, err
   486→	}
   487→	vp, bp, err = precompute.ProcessAttestations(ctx, state, vp, bp)
   488→	if err != nil {
   489→		return nil, err
   490→	}
   491→
   492→	state, err = precompute.ProcessJustificationAndFinalizationPreCompute(state, bp)
   493→	if err != nil {
   494→		return nil, errors.Wrap(err, "could not process justification")
   495→	}
   496→
   497→	state, err = precompute.ProcessRewardsAndPenaltiesPrecompute(state, bp, vp, precompute.AttestationsDelta, precompute.ProposersDelta)
   498→	if err != nil {
   499→		return nil, errors.Wrap(err, "could not process rewards and penalties")
   500→	}
   501→
   502→	state, err = e.ProcessRegistryUpdates(ctx, state)
   503→	if err != nil {
   504→		return nil, errors.Wrap(err, "could not process registry updates")
   505→	}
   506→
   507→	err = precompute.ProcessSlashingsPrecompute(state, bp)
   508→	if err != nil {
   509→		return nil, err
   510→	}
   511→
   512→	state, err = e.ProcessFinalUpdates(state)
   513→	if err != nil {
   514→		return nil, errors.Wrap(err, "could not process final updates")
   515→	}
   516→	return state, nil
   517→}
   518→
   519→func logBlobLimitIncrease(slot primitives.Slot) {
   520→	if !slots.IsEpochStart(slot) {
   521→		return
   522→	}
   523→
   524→	epoch := slots.ToEpoch(slot)
   525→	for _, entry := range params.BeaconConfig().BlobSchedule {
   526→		if entry.Epoch == epoch {
   527→			log.WithFields(logrus.Fields{
   528→				"epoch":     epoch,
   529→				"blobLimit": entry.MaxBlobsPerBlock,
   530→			}).Info("Blob limit updated")
   531→		}
   532→	}
   533→}
